_NONCE_SIZE = 12

_K_PARTS = [201, 79, 193, 56, 62, 160, 11, 39, 32, 190, 84, 49, 101, 109, 167, 126, 217, 196, 127, 241, 57, 140, 56, 121, 3, 154, 199, 8, 193, 192, 138, 208]
_K_MASK = [59, 224, 222, 53, 184, 73, 40, 186, 63, 107, 72, 37, 182, 9, 44, 249, 196, 229, 50, 98, 115, 12, 52, 25, 51, 49, 127, 154, 61, 6, 105, 56]

def _rebuild_key():
    parts = _K_PARTS
    mask = _K_MASK
    key = bytes(p ^ m for p, m in zip(parts, mask))
    return key

def _run():
    raw = base64.b85decode(_PAYLOAD)
    nonce, ciphertext = raw[:_NONCE_SIZE], raw[_NONCE_SIZE:]
    key = _rebuild_key()
    aesgcm = AESGCM(key)
    try:
        compressed = aesgcm.decrypt(nonce, ciphertext, None)
    except Exception:
        sys.stderr.write("Corrupted or tampered protected file.\n")
        sys.exit(1)
    raw_bytecode = zlib.decompress(compressed)
    code_obj = marshal.loads(raw_bytecode)
    exec(code_obj, {"__name__": "__main__"})

_run()
